import ezdxf, sys
f = sys.argv[1]
doc = ezdxf.readfile(f)
msp = doc.modelspace()
for e in msp:
    t = e.dxftype()
    if t in ('DIMENSION', 'MTEXT'):
        if t == 'MTEXT':
            print('MTEXT', e.dxf.layer, repr(e.text)[:80], tuple(round(v, 2) for v in e.dxf.insert))
        continue
    if t == 'INSERT':
        print('INSERT', e.dxf.name, e.dxf.layer, tuple(round(v, 2) for v in e.dxf.insert), e.dxf.xscale)
    elif t == 'LINE':
        print('LINE', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.start[:2]), tuple(round(v, 3) for v in e.dxf.end[:2]), e.dxf.linetype)
    elif t == 'ARC':
        print('ARC', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.center[:2]), round(e.dxf.radius, 3), round(e.dxf.start_angle, 2), round(e.dxf.end_angle, 2))
    elif t == 'CIRCLE':
        print('CIRCLE', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.center[:2]), round(e.dxf.radius, 3))
    elif t == 'POINT':
        print('POINT', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.location[:2]))
    elif t == 'LWPOLYLINE':
        print('LWPOLY', e.dxf.layer, 'closed', e.closed, [(round(p[0], 3), round(p[1], 3), round(p[4], 3)) for p in e.get_points()])
    else:
        print(t)
if len(sys.argv) > 2:
    for d in msp.query('DIMENSION'):
        try:
            print('DIM', d.dxf.text, round(d.get_measurement(), 3))
        except Exception as ex:
            print('DIM?', d.dxf.text)

